<?php
require_once __DIR__.'/Pdf.php';
function cxMixCsvNumber($v) {return str_replace(' ','',cxDisplayDecimal($v));}
function cxMixCsvCell($v) {
    if($v===null)return 'Pendiente';$text=(string)$v;
    if(preg_match('/^[\s\x00-\x1F]*[=+@-]/u',$text))$text="'".$text;
    return $text;
}
function cxMixCsv(array $r,$section) {
    $out=fopen('php://temp','w+');fwrite($out,"\xEF\xBB\xBF");$write=function($row)use($out){fputcsv($out,array_map('cxMixCsvCell',$row),';','"','');};
    $write(['Control de mezclas',$r['desde'],$r['hasta'],$r['planta'],$r['emisor'],'Consultado '.$r['consultadoEn'].' America/Lima',$r['resumen']['incluyePruebas']?'INCLUYE DATOS DE PRUEBA':'']);
    if($section==='cargas'){
        $write(['Fecha programada','Programa','Revisión','Pedido','Proforma','Carga','Empresa emisora','RUC emisor','Cliente','Documento cliente','Obra','Dirección obra','Receta / versión','Estado receta','Elemento','Slump','Unidad slump','Descarga','m³ nominales','m³ reales','Guía','Salida real','Mixer','Conductor','Responsables','Estado programa','Estado carga','Incluida en totales','Incidencias']);
        foreach($r['cargas'] as $c){$owners=[];foreach($c['responsables'] as $u)$owners[]=$u['Area'].': '.$u['Nombre'].' ('.$u['Usuario'].')';$write([$c['fecha'],$c['programacion'],$c['revision'],$c['pedido'],$c['proforma'],$c['carga'],$c['emisor'],$c['rucEmisor'],$c['cliente'],$c['documentoCliente'],$c['obra'],$c['direccionObra'],$c['receta'],$c['estadoReceta'],$c['elemento'],cxMixCsvNumber($c['slump']),$c['unidadSlump'],$c['descarga'],cxMixCsvNumber($c['m3Nominal']),null,null,null,$c['mixer'],$c['conductor'],implode(' / ',$owners),$c['estado'],$c['estadoCarga'],$c['incluida']?'Sí':'No',implode(' / ',$c['incidencias'])]);}
    }else{
        $write(['Fecha programada','Programa','Pedido','Carga','Empresa emisora','Cliente','Receta / versión','Insumo','Unidad','Base','Dosis por m³','m³ nominales','Requerimiento nominal','Requerimiento corregido','Consumo real','Diferencia real menos nominal','Incluida en totales','Provisional']);
        foreach($r['insumos'] as $c)$write([$c['fecha'],$c['programacion'],$c['pedido'],$c['carga'],$c['emisor'],$c['cliente'],$c['receta'],$c['producto'],$c['unidad'],$c['base'],cxMixCsvNumber($c['dosisPorM3']),cxMixCsvNumber($c['m3Nominal']),cxMixCsvNumber($c['nominal']),null,null,null,$c['incluida']?'Sí':'No',$c['provisional']?'Sí':'No']);
    }
    $write([]);$write([$r['criterio']]);rewind($out);$result=stream_get_contents($out);fclose($out);return $result;
}
function cxMixHtmlTable($headers,$rows) {
    $h='<table><thead><tr>';foreach($headers as $v)$h.='<th>'.cxEscape($v).'</th>';$h.='</tr></thead><tbody>';
    foreach($rows as $row){$h.='<tr>';foreach($row as $v)$h.='<td>'.($v===null?'<span class="pending">Pendiente</span>':cxEscape($v)).'</td>';$h.='</tr>';}
    return $h.'</tbody></table>';
}
function cxMixControlHtml(array $r) {
    $n=function($v){return cxDisplayDecimal($v);};$s=$r['resumen'];
    $left=cxDocumentLogo(['LogoPath'=>'/resources/images/wuanuko-mix-logo-transparente.png']);$rightFile=dirname(__DIR__,2).'/resources/images/neurosystem-menu-original.png';$right=is_file($rightFile)?'data:image/png;base64,'.base64_encode(file_get_contents($rightFile)):'';
    $h='<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Control de mezclas</title><style>@page{margin:24px 25px 30px}body{font-family:Arial,Helvetica,sans-serif;font-size:10px;font-weight:600;line-height:1.3;color:#173344}h1{font-size:21px;color:#075766;margin:0 0 5px}h2{font-size:13px;color:#075766;margin:18px 0 7px;page-break-after:avoid}.new-page{page-break-before:always}.page-number{position:fixed;bottom:-18px;right:0;font-size:8px;color:#536f7a}.page-number span:before{content:counter(page)}p{margin:5px 0}table{width:100%;border-collapse:collapse;table-layout:fixed;margin:6px 0 12px}thead{display:table-header-group}th{background:#075766;color:#fff;font-size:9px;padding:7px 5px;text-align:left}td{border-bottom:1px solid #cbdde2;padding:7px 5px;vertical-align:top;overflow-wrap:break-word;word-wrap:break-word}tr{page-break-inside:avoid}.pending{color:#657983}.note{padding:8px;background:#eef5f8;border-left:3px solid #0b8690}.brand td{border:0;padding:0}.brand img{height:55px;max-width:110px}.muted{color:#536f7a;font-size:9px}.footer{border-top:1px solid #b9d0d8;padding-top:8px;font-size:9px;margin-top:15px}</style></head><body><div class="page-number">Control de mezclas | Página <span></span></div>';
    $h.='<table class="brand"><tr><td style="width:15%">'.($left?'<img src="'.$left.'" style="width:77px;height:55px">':'WUANUKO MIX').'</td><td style="width:65%"><h1>Control de mezclas e insumos</h1><strong>'.cxEscape($r['gestion']).'</strong><p>'.cxEscape($r['planta'].' | '.$r['desde'].' al '.$r['hasta']).'</p></td><td style="width:20%;text-align:right;background:#172b3a;padding:8px;vertical-align:middle">'.($right?'<img src="'.$right.'" style="width:110px;height:28px">':'NEUROSYSTEM').'</td></tr></table>';
    if($s['incluyePruebas'])$h.='<p class="note"><strong>INCLUYE DATOS DE PRUEBA - NO UTILIZAR COMO ORDEN DE PRODUCCIÓN</strong></p>';
    $h.='<p><strong>Emisor:</strong> '.cxEscape($r['emisor']).' | <strong>Consulta:</strong> '.cxEscape($r['consultadoEn']).' America/Lima</p><p class="note">'.cxEscape($r['criterio']).' Los consumos reales, correcciones, guía y salida real están pendientes de registro en producción.</p>';
    $h.=cxMixHtmlTable(['m³ nominales vigentes','Cargas divididas','Sin dividir','Sin dosificación','Receta no aprobada'],[[$n($s['m3Nominal']),$s['cargas'],$s['sinDividir'],$s['sinReceta'],$s['recetaNoAprobada']]]);
    $h.='<h2>Resumen diario</h2>'.cxMixHtmlTable(['Fecha','m³ nominales','Cargas','Sin dividir','m³ reales'],array_map(function($d)use($n){return [$d['fecha'],$n($d['m3Nominal']),$d['cargas'],$d['sinDividir'],null];},$r['dias']));
    $h.='<h2>Insumos nominales del período'.($s['insumosParciales']?' - total parcial: faltan recetas':'').'</h2>'.cxMixHtmlTable(['Insumo','Unidad / base','Requerimiento nominal','Corregido','Real','Diferencia','Condición'],array_map(function($m)use($n){return [$m['producto'],$m['unidad'].' / '.$m['base'],$n($m['nominal']),null,null,null,$m['provisional']?'Provisional':'Nominal'];},$r['totalesInsumos']));
    $h.='<h2'.($r['cargas']?' class="new-page"':'').'>Cargas y pedidos</h2>'.cxMixHtmlTable(['Inicio / carga','Programa / pedido','Emisor','Cliente / obra','Receta / elemento','m³ nominal','m³ real / guía','Mixer / conductor','Estado / observaciones'],array_map(function($c)use($n){return [$c['fecha'].' / '.($c['carga']??'Sin dividir'),$c['programacion'].' / '.$c['pedido'],$c['emisor'],$c['cliente'].' / '.$c['obra'],$c['receta'].' / '.$c['elemento'],$n($c['m3Nominal']),null,$c['mixer'].' / '.$c['conductor'],$c['estado'].' / '.$c['estadoCarga'].($c['incluida']?'':' / EXCLUIDA')];},$r['cargas']));
    $h.='<h2>Detalle de requerimientos por carga</h2>'.cxMixHtmlTable(['Programa / carga','Pedido','Insumo','Dosis / m³','m³ nominal','Nominal','Unidad / base','Corregido / real','Condición'],array_map(function($m)use($n){return [$m['programacion'].' / '.($m['carga']??'Sin dividir'),$m['pedido'],$m['producto'],$n($m['dosisPorM3']),$n($m['m3Nominal']),$n($m['nominal']),$m['unidad'].' / '.$m['base'],null,($m['incluida']?'Incluida':'Excluida').($m['provisional']?' / Provisional':'')];},$r['insumos']));
    $responsibles=[];foreach($r['cargas'] as $c){if(isset($responsibles[$c['idProgramacion']]))continue;$names=[];foreach($c['responsables'] as $u)$names[]=$u['Area'].': '.$u['Nombre'].' ('.$u['Usuario'].')';$responsibles[$c['idProgramacion']]=[$c['programacion'],$c['pedido'],implode(' / ',$names)];}
    $h.='<h2'.($r['cargas']?' class="new-page"':'').'>Responsables registrados por área</h2>'.cxMixHtmlTable(['Programa','Pedido','Responsables'],array_values($responsibles));
    $issues=[];foreach($r['cargas'] as $c)if($c['incidencias'])$issues[$c['idProgramacion']]=[$c['programacion'],implode(' / ',$c['incidencias'])];if($issues)$h.='<h2>Datos pendientes por suministro</h2>'.cxMixHtmlTable(['Programa','Detalle'],array_values($issues));
    $h.='<h2>Existencias y alertas actuales</h2><p class="note">'.cxEscape($r['criterioStock']).'</p>'.cxMixHtmlTable(['Insumo','Unidad / base','Físico actual','Reservado','Borradores hasta fin','Saldo proyectado','Compra sugerida','Comprar antes','Estado'],array_map(function($m)use($n){return [$m['Producto'],$m['Unidad'].' / '.$m['BaseStock'],$n($m['stock']['fisico']),$n($m['stock']['reservadoNominal']),$n($m['demandaBorrador']),$n($m['saldoProyectado']),$n($m['compraSugerida']),$m['comprarAntes']??'Sin plazo',$m['estado']];},$r['stockActual']['materiales']));
    return $h.'<div class="footer">NEUROSOFT | Control de mezclas | '.cxEscape($r['desde'].' al '.$r['hasta']).' | '.cxEscape($r['consultadoEn']).' America/Lima. Los aditivos se controlan por producto en litros; una identidad o unidad pendiente requiere revisión técnica.</div></body></html>';
}
